# aeneid-081 (X.791-908): t is cut from the edition by A.cut; l, i, n drafted from the Latin.
import sys, os
HERE = os.path.dirname(os.path.abspath(__file__)); sys.path.insert(0, HERE); sys.path.insert(0, os.path.join(HERE, '..', '..'))
import aeneid_lib as A

TITLE = 'Mors Lausi et Mezentii'
PART = "The Deaths of Lausus and Mezentius (X.791–908)"
TITLE_EN = "The Deaths of Lausus and Mezentius — Aeneid X.791–908"
ABOUT = ("Lausus, the young son of Mezentius, steps between his wounded father and Aeneas's sword, and his comrades cover the old man's retreat with a storm of spears. "
"Aeneas waits under his shield like a traveller sheltering from hail, warns the boy off, and then, his anger rising, kills him. "
"Seeing the dead boy's face, he is overcome with pity: he leaves Lausus his armour, gives him back to his people for burial, and lifts him from the ground himself. "
"By the Tiber, Mezentius, washing his wound, hears the mourning and knows what has happened. He blames himself, the exiled tyrant whose crimes have stained his son's name, and resolves to die. "
"He mounts his horse Rhaebus, speaks to it as a companion, and rides at Aeneas, circling him and hurling spear after spear into his shield, until Aeneas kills the horse and it falls on its rider. "
"Mezentius asks only that his body be buried beside his son's, safe from his people's hatred, and takes the sword in his throat. So Book X ends. "
"The poet's address to Lausus, the father's lament and the hero speaking to his horse have Homeric models, but Aeneas's pity for the boy he has just killed is something Homer's victors rarely show.")

U = [
(793, 'silebo.',
 """Here the fall of your hard death, and your most noble deeds,\nif any belief to so great an act the long ages will bring,\nnot, for my part, nor you, young man to be remembered, will I pass over in silence.""",
 """Here I will not pass over in silence the fate of your cruel death and your splendid deeds, if the ages to come will believe so great an act, nor you yourself, young man, who deserve to be remembered.""",
 """A new paragraph in Greenough, and the poet breaks into his own story to speak to Lausus, an apostrophe, as he did for Nisus and Euryalus (IX.446–449). 'Hic', 'here', at this point in the narrative. 'casum… facta', objects of 'silebo', 'I will keep silent about', used transitively. 'siqua… vetustas', 'if antiquity (the long ages) will bring any belief to so great a deed'; 'siqua' is Greenough's one-word spelling of 'si qua'. 'non equidem nec te', a double negative that stays negative: 'not (your deeds), nor you either'. 'memorande', vocative of the gerundive, 'you who must be remembered'. Elision 'tuaqu(e) optima'; prodelision 'tanto (e)st'."""),
(795, 'trahebat:',
 """He, his foot drawing back, both disabled and bound in,\nwas giving ground, and in his shield the enemy shaft was dragging:""",
 """Mezentius was giving ground, crippled and hampered, dragging the enemy's spear along in his shield:""",
 """'Ille', Mezentius, wounded in the groin at the end of the last part (785–786). 'pedem referens', 'carrying back his foot', the regular phrase for retreating step by step. 'inutilis', 'useless', disabled for fighting. 'inque ligatus', 'and bound in', tmesis: the compound 'inligatus' split by '-que', a touch of archaic style; the spear still fixed in his shield hampers him. 'clipeo', 'in his shield', ablative of place. 'inimicum hastile', Aeneas's spear-shaft. The colon throws the weight onto what Lausus does next. Elisions 'clipeoqu(e) inimicum', 'inimic(um) hastile'."""),
(799, 'sustinuit.',
 """burst forth the young man and mingled himself in the fighting,\nand, of him already rising and bringing a blow with his right hand,\nof Aeneas, he went in under the sword-point, and him by delaying\nheld off.""",
 """the young man burst forward and threw himself into the fighting, and just as Aeneas rose to bring his sword down in a blow, he came in under the point and held him off, checking him.""",
 """'prorupit', 'burst forth'; the Latin Library has 'proripuit', 'snatched himself forward', the same act. 'iuvenis', Lausus, unnamed until 810. 'immiscuit armis', 'mingled himself with the arms', dative with a compound verb. 'adsurgentis… ferentis', genitive singular, agreeing with 'Aeneae' held over to the next line: Aeneas rising on his toes to bring down a blow. 'subiit mucronem', 'went under the point', took the stroke on himself. 'ipsumque morando / sustinuit', 'and held (Aeneas) himself back by delaying him', with the gerund 'morando'; the verb is held over and stopped short. Elisions 'sesequ(e) immiscuit', 'iamqu(e) adsurgentis', 'Aenea(e) subiit', 'mucron(em) ipsumque'."""),
(802, 'missilibus.',
 """His comrades with a great shout follow,\nso that the father, by his son's shield protected, might get away,\nand weapons they hurl, and drive back from afar the enemy\nwith missiles.""",
 """His comrades followed with a great shout, so that the father could withdraw under cover of his son's shield, and they showered weapons and drove the enemy back from a distance with their missiles.""",
 """'Socii', Lausus's men. 'dum… abiret', 'until (and so that) the father might get away', 'dum' with the subjunctive of purpose, here in past time. 'genitor', the poetic word for father, and 'nati', 'of the son', set side by side: father and son run through the whole part. 'parma', the small round shield of a light-armed fighter, Lausus's. 'proturbant', 'drive back'; the Latin Library has 'perturbant', 'throw into confusion', a slightly different sense. 'eminus', 'from a distance', and 'missilibus', 'with things thrown', held over the line-end. Elision 'proturbantqu(e) eminus'."""),
(802, 'tenet se.',
 """Rages Aeneas, and covered holds himself.""",
 """Aeneas raged, but kept himself under cover.""",
 """Two short clauses at the end of a line. 'Furit', 'rages', put first: Aeneas is furious, but must stand his ground under the shower of spears. 'tectus… tenet se', 'covered, he holds himself (still)', behind his shield. The line ends on the monosyllable 'se', an unusual close that checks the rhythm as Aeneas himself is checked. No elisions."""),
(806, 'saxi,',
 """And as, whenever, with hail poured out, the storm-clouds\nrush down, every ploughman from the fields scatters,\nand every farmer, and in a safe stronghold hides the traveller,\neither in a river's banks or of a high rock in the vault,""",
 """And just as, when storm-clouds burst and pour down hail, every ploughman and every farmer scatters from the fields, and the traveller hides in some safe shelter, under a river's overhanging bank or in the vault of a high rock,""",
 """A simile from Italian country life. 'velut… siquando', 'just as, whenever'. 'effusa… grandine', ablative absolute, 'the hail having been poured out'. 'nimbi', 'rain-clouds'; 'praecipitant', 'rush down', intransitive. 'omnis… arator / omnis et agricola', nominative singulars, 'every ploughman and every farmer', the repeated 'omnis' (anaphora) emptying the fields. 'tuta… arce', 'in a safe citadel', here any secure refuge, explained by the next line: 'amnis ripis', under the overhanging banks of a river, or 'alti fornice saxi', 'in the arch of a high rock'. Elisions 'agricol(a) et', 'arc(e) viator'."""),
(808, 'diem:',
 """while it rains on the earth, so that they may, the sun brought back,\nwork the day:""",
 """while the rain falls on the land, so that when the sun returns they may get on with the day's work:""",
 """'dum pluit', 'while it rains', the impersonal verb. 'ut possint', a purpose clause, 'so that they may be able'. 'sole reducto', ablative absolute, 'the sun having been brought back'. 'exercere diem', 'to work the day', a bold phrase: to put the daylight to use in their labour. The detail makes the sheltering sensible and brief, not cowardly, and so it suits Aeneas, who waits under cover until the storm of spears is spent. No elisions."""),
(810, 'minatur:',
 """so, buried on every side by missiles,\nAeneas the cloud of war, until it thunders itself all out,\nendures, and Lausus he scolds, and Lausus threatens:""",
 """so Aeneas, buried on every side under missiles, bore the cloud of war until it had thundered itself out, and shouted reproaches and threats at Lausus:""",
 """'sic' takes up 'velut' from 803. 'obrutus', 'overwhelmed, buried'. 'nubem belli', 'the cloud of war', the shower of missiles, carrying on the storm image. 'dum detonet omnis', 'until it all thunders itself out', 'dum' with the subjunctive of expectation; 'omnis' is nominative, agreeing with the cloud as subject. 'Lausum… Lausoque', the name repeated in two cases (polyptoton), first accusative with 'increpitat', 'scolds', then dative with 'minatur', 'threatens'. Here at last the young man is named. Elision 'Laus(um) increpitat'."""),
(812, 'tua.',
 """“Where, boy about to die, do you rush, and things greater than your strength dare?\nIt deceives you, unguarded, your devotion.”""",
 """“Where are you running to your death, daring more than your strength can carry? Your love for your father is blinding you to the danger.”""",
 """'moriture', vocative of the future participle, 'you who are about to die', with 'ruis', 'rush'. 'maiora viribus', 'things greater than your strength', ablative of comparison. 'Fallit te incautum pietas tua', 'your pietas deceives you, off your guard': 'pietas' here is a son's devotion to his father, the very quality Aeneas is named for, and the line is often quoted. Aeneas speaks as a warning, half in pity. The closing speech mark is printed joined to the next word; see the next unit. Elision 't(e) incautum'."""),
(813, 'demens;',
 """None the less he\nexults, out of his mind;""",
 """None the less he leapt to the attack in his frenzy;""",
 """The print has 'tua. ”Nec', with the closing speech mark joined to the next word, a misprint for 'tua.” Nec', corrected here: the speech ends with 'tua'. 'Nec minus', 'and no less', in spite of the warning. 'exsultat', 'leaps up, prances', a word used of horses and of eager fighters. 'demens', 'out of his mind', with the recklessness of youth; Virgil's judgment is pitying, not scornful. No elisions."""),
(815, 'legunt:',
 """and fierce, now higher, the angers\nfor the Dardan leader rise, and the last for Lausus\nthe Parcae threads gather:""",
 """and now the anger of the Dardan leader rose higher and fiercer, and the Fates gathered in the last threads of Lausus's life:""",
 """'saevae… irae', 'savage angers', plural, rising 'altius', 'higher', like a swelling sea. 'Dardanio… ductori', dative of reference, 'for the Dardanian leader', Aeneas, descended from Dardanus, founder of Troy's royal line. 'extrema… fila', 'the last threads'. The 'Parcae' are the three Fates, who spin, measure and cut each life's thread; 'legunt', 'gather up', winds in the end of the thread as the spinning finishes. Elisions 'iamqu(e) altius', 'ductor(i) extremaque'."""),
(816, 'recondit.',
 """for his strong sword\nAeneas drives through the middle of the youth and hides it whole.""",
 """for Aeneas drove his strong sword clean through the young man's body and buried the whole blade.""",
 """'namque', 'for', explaining the Fates' work by the blow. 'exigit', 'drives through', from 'ex-ago'. 'per medium… iuvenem', 'through the middle of the young man'. 'totumque recondit', 'and hides it whole', buries the entire blade. The word order sets 'Aeneas' at the head of the line beside 'iuvenem', the grown warrior and the boy. Elisions 'namqu(e) exigit', 'medi(um) Aeneas'."""),
(820, 'reliquit.',
 """Passed through both the shield the point, light arms for one so threatening,\nand the tunic, which with soft gold his mother had spun,\nand filled the fold the blood; then life through the air\nwithdrew, sorrowing, to the shades, and the body left.""",
 """The point passed through the shield, too light a defence for such bold threats, and through the tunic his mother had woven with soft gold thread, and blood filled the folds at his breast; then his life withdrew sorrowing through the air to the shades and left the body behind.""",
 """'Transiit et parmam… et tunicam', 'passed through both the shield and the tunic'. 'levia arma minacis', 'light arms for one so threatening', in apposition to 'parmam': a small shield for so bold a fighter. 'neverat', pluperfect of 'neo', 'had spun'; the mother's work makes the death a family's loss. 'sinum', the fold of the tunic over the breast. 'vita… concessit maesta ad manis', 'life withdrew, sorrowing, to the shades', 'manis' the '-is' accusative plural; the soul grieving as it goes recalls Homer's lines on the deaths of Patroclus and Hector (Iliad 16.856–857, 22.362–363). Elisions 'levi(a) arma', 'maest(a) ad'."""),
(824, 'imago.',
 """But truly, when the face he saw of the dying boy, and the features,\nthe features, Anchises' son, growing pale in wondrous ways,\nhe groaned, pitying, deeply, and his right hand stretched out,\nand into his mind there entered the image of devotion to a father.""",
 """But when the son of Anchises saw the look on the dying boy's face, that face growing pale in ways so strange, he groaned deeply in pity and stretched out his hand, as the picture of his own love for his father came into his mind.""",
 """Now the killer's pity. 'At vero', 'but truly', a strong turn. 'ora, / ora', the word repeated across the line-end (anadiplosis) as Aeneas looks again. 'Anchisiades', 'son of Anchises', a Greek patronymic, chosen for a passage about fathers and sons. 'modis… miris', 'in wondrous ways', a phrase from Lucretius (1.123, of ghosts 'pale in wondrous ways'). 'dextram tetendit', a gesture of pity. 'patriae pietatis imago', 'the image of devotion to a father': Lausus dying for his father calls up Aeneas's own love for Anchises (some take it also of his love for his son). Elision 'ver(o) ut'."""),
(826, 'dignum?',
 """“What to you now, boy to be pitied, for those glories,\nwhat will dutiful Aeneas give, worthy of so great a nature?""",
 """“What can dutiful Aeneas give you now, poor boy, for such glorious deeds — what gift worthy of so noble a spirit?""",
 """Aeneas speaks to the dead boy. 'Quid… quid', the question doubled. 'miserande', vocative of the gerundive, 'you who are to be pitied'. 'pro laudibus istis', 'for those glories of yours', 'istis' pointing to the person addressed. 'pius Aeneas': Aeneas names himself by his own epithet, as he did to Venus at I.378, and the word answers 'pietas' at 812 and 824. 'indole', 'inborn character, promise', ablative with 'dignum', 'worthy of'. No elisions."""),
(828, 'remitto.',
 """The arms in which you rejoiced, keep as your own, and you to your forefathers'\nshades and ashes, if that is any care, I send back.""",
 """Keep the arms you took such pride in, for they are yours; and I give you back to the shades and ashes of your fathers, if that is any concern to the dead.""",
 """Aeneas will not strip the body, though a dead enemy's armour was the victor's right in Homer and in Virgil; contrast Turnus, who takes Pallas's belt (X.495–500) and will die for it. 'quibus laetatus', with 'es' understood, 'in which you took delight', 'laetor' with the ablative. 'parentum / manibus et cineri', 'to the shades and ash of your forefathers', burial in the family tomb. 'siqua est ea cura', 'if that care is anything', to the dead. 'remitto', 'I send back'. Elision 'siqu(a) est'."""),
(830, 'cadis.',
 """This, though, unhappy boy, will console your wretched death:\nby great Aeneas's right hand you fall.”""",
 """Yet this, poor boy, will be a comfort in your pitiful death: the hand that brings you down is the hand of great Aeneas.”""",
 """'Hoc', explained by the next line. 'infelix', 'unlucky one', in effect a vocative. 'solabere', second-person future in '-re' for '-ris', 'you will console'; the death itself is what is consoled. 'Aeneae magni dextra cadis', 'by the right hand of great Aeneas you fall', ablative of means: to die by a famous hand was some honour in the heroic code; Camilla makes the same boast at XI.688–689. Aeneas offers it sadly, not in triumph. On the closing speech mark, see the next unit. No elisions."""),
(832, 'capillos.',
 """He chides, unasked,\nthe hanging-back comrades, and from the ground lifts the boy himself,\nwith blood fouling his hair, combed as custom was.""",
 """Then he went further and called on the boy's hesitating comrades, and himself raised Lausus from the ground, his hair, combed and dressed as custom required, fouled with blood.""",
 """The print has 'cadis. ”Increpat', with the closing speech mark joined to the next word, a misprint for 'cadis.” Increpat', corrected here: the speech ends with 'cadis'. 'ultro', 'beyond what was asked', 'even': the enemy calls Lausus's men forward to take the body. 'cunctantis', '-is' accusative plural, 'hanging back' for fear of Aeneas. 'ipsum', 'him', the body. 'turpantem', 'disfiguring', with the dead boy as subject: his blood fouls his own hair. 'comptos de more', 'combed according to custom', the care of a young noble. No elisions."""),
(835, 'trunco.',
 """Meanwhile the father, by the Tiber river's water,\nhis wounds was drying with clear water, and his body resting,\nof a tree leaning on the trunk.""",
 """Meanwhile his father, beside the waters of the Tiber, was washing and staunching his wound, resting his body against the trunk of a tree.""",
 """A new paragraph in Greenough, and a change of scene: Mezentius does not yet know. 'genitor', 'the father', with no name: the word carries the scene. 'Tiberini… fluminis', 'of the Tiber river', 'Tiberinus' the adjective. 'volnera siccabat lymphis', 'was drying his wounds with water', washing and stanching them; 'volnera' is Greenough's spelling of 'vulnera', a poetic plural for one wound. 'lymphis', 'clear water'. 'levabat', 'was easing'. 'adclinis', 'leaning', with the dative 'trunco'. The imperfects paint a still scene. Elision 'Tiberin(i) ad'."""),
(836, 'quiescunt.',
 """Some way off, bronze, from the branches\nhangs the helmet, and on the meadow the heavy arms rest.""",
 """Some way off, his bronze helmet hung from the branches, and his heavy armour lay at rest on the grass.""",
 """'Procul', 'at a distance'. 'aerea… galea', 'the bronze helmet', adjective and noun spread across the line. 'ramis', ablative of place, 'from the branches'. 'prato', 'on the meadow', ablative of place without a preposition. 'quiescunt', 'are at rest': the armour rests while its owner cannot. The quiet detail delays the news. Elisions 'gale(a) et', 'gravi(a) arma'."""),
(838, 'barbam;',
 """Stand chosen around him young men: he himself, sick, panting,\nhis neck eases, spread as to his combed-down beard upon his chest;""",
 """Chosen young men stood around him, while he himself, sick and short of breath, eased his neck, his long combed beard spread over his chest;""",
 """'lecti… iuvenes', 'picked young men', his guard. 'aeger anhelans', 'sick, gasping', two words without a connective (asyndeton). 'colla fovet', 'warms, eases his neck', the plural 'colla' for one neck, as often in verse. 'fusus propexam in pectore barbam', 'spread, as to his combed-down beard, on his breast': the passive participle 'fusus' with an accusative of the part affected, a Greek construction Virgil likes. The old man's beard sets him against the boy. Elisions 'ips(e) aeger', 'propex(am) in'."""),
(840, 'parentis.',
 """Many things about Lausus he keeps asking, and many he sends\nwho should call him back and bear the orders of his anxious father.""",
 """Again and again he asked after Lausus, and sent man after man to call him back and bring him the orders of his anxious father.""",
 """'multa super Lauso rogitat', 'he keeps asking many things about Lausus', 'super' with the ablative, 'concerning', and 'rogitat' the frequentative of 'rogo', 'ask repeatedly'. 'multumque remittit / qui revocent', 'and sends many (messengers) to call him back', a relative clause of purpose with the subjunctive; 'multum' for 'multos' is unusual, and some take it as an adverb, 'again and again'. 'maesti… parentis', 'of his sorrowing (anxious) father'. No elisions."""),
(842, 'victum.',
 """But Lausus his comrades, lifeless, upon his arms were carrying,\nweeping, a huge man, and by a huge wound overcome.""",
 """But his comrades were bearing Lausus, lifeless, upon his shield, weeping as they came: a great figure, brought down by a great wound.""",
 """'At', the turn back to Lausus. 'exanimem', 'lifeless'. 'super arma', 'on his armour', carried on his shield as on a bier, as Pallas is carried back on his (X.505–506). 'ingentem atque ingenti', the adjective repeated in two cases: Lausus is 'huge' in the heroic sense, greater than life, and his wound matches him. 'victum', 'conquered', the last word. Elisions 'soci(i) exanimem', 'ingent(em) atqu(e) ingenti'."""),
(843, 'mens:',
 """Knew from afar the wailing, foreboding of evil, his mind:""",
 """His mind, already foreseeing disaster, knew the sound of mourning from far off:""",
 """'Agnovit', put first: he understands before he sees. 'longe', 'from afar'. 'gemitum', 'the lamentation' of the men carrying the body. 'praesaga mali mens', 'his mind, foreboding of evil', 'praesagus' with the genitive; the subject comes last. The 'm' sounds of 'mali mens' close the line heavily. No elisions."""),
(845, 'inhaeret.',
 """his white hair with much dust he disfigures, and both\nto the sky he stretches his palms, and to the body clings.""",
 """he fouled his white hair with handfuls of dust, stretched both hands to the sky, and clung to the body.""",
 """The gestures of ancient mourning. 'canitiem', 'greyness', the abstract for the grey hair itself. 'deformat pulvere', 'disfigures with dust'; Achilles pours dust over his head at the news of Patroclus's death (Iliad 18.23–24), and Priam grovels in the dirt mourning Hector (Iliad 22.414). 'ambas… palmas', 'both palms', framing the line-end, raised in prayer or reproach. 'corpore inhaeret', 'clings to the body', dative with the compound. Elisions 'pulver(e) et', 'corpor(e) inhaeret'."""),
(848, 'genui?',
 """“Did so great a hold on me, of living, son, the pleasure,\nthat in my place to the enemy's I let go under right hand\nhim whom I begot?""",
 """“Was I held by such a craving to live, my son, that I let the boy I fathered go in my place beneath the enemy's sword?""",
 """Mezentius's lament. 'Tantane… voluptas', 'so great a pleasure of living', 'vivendi' the genitive of the gerund; 'ut… paterer', a result clause, 'that I allowed'. 'pro me', 'in my place'. 'succedere', 'to go under', with the dative 'hostili… dextrae', 'the enemy's right hand'. 'quem genui', 'him whom I begot', with 'eum' understood as subject of 'succedere': the father names the son by his own act of fathering. 'nate', vocative, 'son'. Elision 'm(e) hostili'."""),
(849, 'vivens?',
 """Through these your wounds, I, the father, am I saved,\nby your death living?""",
 """Am I, your father, saved by these wounds of yours, alive because you are dead?""",
 """'Tuane haec… per volnera', 'through these wounds of yours', with '-ne' putting the question on the emphatic 'tua'. 'genitor', in apposition to the subject of 'servor', 'I, the father, am saved'. 'morte tua vivens', 'living by your death', the antithesis of life and death closing the question. The father saved by the son reverses the order of nature: a parent should die first. Elision 'Tuan(e) haec'."""),
(850, 'adactum!',
 """Alas, now to me, wretched, at last\nruin is unhappy, now deep the wound driven in!""",
 """Alas, only now has ruin truly come upon me in my misery, only now is the wound driven deep!""",
 """'nunc… demum', 'now at last'. 'misero mihi', dative of reference. 'exitium infelix', 'ruin (is) unhappy', with 'est' understood: his own wound was nothing; this is the real destruction. Many editors read 'exilium', 'exile', meaning that only now is his banishment bitter, which suits 852; Greenough prints 'exitium', and the Latin Library agrees. 'alte… adactum', 'driven in deep', with 'est' understood. The repeated 'nunc' marks the sudden realisation. Elision 'exiti(um) infelix'."""),
(852, 'paternis.',
 """I too, son, your name have stained with my crime,\ndriven out through hatred from the throne and sceptre of my fathers.""",
 """It was I, too, my son, who stained your name with my guilt, driven by my people's hatred from the throne and the sceptre of my fathers.""",
 """'Idem ego', 'I the same', 'I also': the father who caused his death has also shamed his name. 'maculavi crimine', 'stained with (my) crime'. 'pulsus ob invidiam', 'driven out because of hatred': the people of Caere rose against his cruelty (VIII.481–495). 'solio sceptrisque paternis', ablatives of separation, 'from the throne and the ancestral sceptre', 'sceptris' a poetic plural. Elision 'Id(em) ego'."""),
(853, 'meorum:',
 """I had owed to my country punishment, and to the hatreds of my own:""",
 """I owed my country a penalty, and my people's hatred its due:""",
 """'Debueram', pluperfect, 'I had owed', in the sense 'I ought long since to have paid'. 'poenas… patriae… odiisque meorum', 'penalties to my country and to the hatreds of my own people', 'meorum' masculine, 'of my own', his former subjects. Mezentius, the scorner of the gods, now owns his guilt; Virgil gives him a late dignity. No elisions."""),
(854, 'dedissem!',
 """through every death my guilty life I myself should have given!""",
 """I should have given up this guilty life myself, through every kind of death!""",
 """'omnis per mortis', 'through all deaths', 'omnis… mortis' accusative plurals in '-is' (you have seen this often), with 'per' set between them. 'animam sontem', 'my guilty soul'. 'ipse', 'I myself', not my son. 'dedissem', pluperfect subjunctive of an obligation not met in past time, 'I should have given'. His people had demanded him for execution (VIII.494–495). Elision 'sont(em) ipse'."""),
(855, 'relinquo.',
 """Now I live, and not yet men and the light do I leave.""",
 """As it is, I am alive, and still I do not leave mankind and the light of day.""",
 """'Nunc', 'as it is'. 'neque adhuc', 'and not yet'. 'homines lucemque', 'men and the light', the world of the living; to see the light is to be alive, in Homer and in Virgil. The line is plain and slow, with no ornament. Elision 'nequ(e) adhuc'."""),
(856, 'linquam.',
 """But I will leave them.”""",
 """But I shall leave them.”""",
 """'Sed linquam', 'but I will leave', the simple verb 'linquo' picking up the compound 'relinquo' of the line before; Virgil often repeats a compound with its simple verb. Two words, a short, decided sentence: he resolves to die. On the closing speech mark, see the next unit. No elisions."""),
(858, 'iubet.',
 """At once, saying this, he raises onto his sick\nthigh himself, and, though the pain from the deep wound slows him,\nnot cast down, his horse to be led he orders.""",
 """As he spoke he raised himself on his wounded thigh and, though the pain of the deep wound held him back, undaunted he ordered his horse to be brought.""",
 """The print has 'linquam. ”Simul', with the closing speech mark joined to the next word, a misprint for 'linquam.” Simul', corrected here: the speech ends with 'linquam'. 'Simul… dicens', 'at the same time saying'. 'attollit… se', 'lifts himself', with 'in aegrum… femur', 'onto his sick thigh', wounded near the groin. 'quamvis… tardet', subjunctive with 'quamvis', 'although'; the Latin Library reads 'quamquam vis… tardat', 'although his strength is slowed', a slightly different sense. 'haud deiectus', 'not cast down', in body or spirit. 'equum duci', accusative and infinitive with 'iubet'. No elisions."""),
(860, 'omnibus.',
 """This was the pride to him,\nthis the comfort; on this from wars as victor he used to come away,\nall of them.""",
 """This horse was his glory, this his comfort; on its back he had come home the victor from every war.""",
 """'Hoc… hoc… hoc', the horse named three times by the pronoun alone (anaphora). 'decus illi', 'a glory to him', dative of possession. 'solamen', 'comfort'. 'bellis… abibat / omnibus', 'he used to come away (victor) from all wars', the imperfect of habit, with 'omnibus' held over to the next line to complete the boast. 'hoc', ablative, 'on this', the horse. No elisions."""),
(860, 'infit:',
 """He addresses the grieving one, and with such words begins:""",
 """He spoke to the grieving horse and began with these words:""",
 """'maerentem', 'grieving', the horse: Achilles' immortal horses weep for Patroclus (Iliad 17.426–440), and Achilles speaks to his horses before battle (Iliad 19.400–403), as Hector does to his (Iliad 8.185–197). 'talibus infit', 'begins with such (words)': 'infit' is an old defective verb found almost only in this form, 'he begins (to speak)'. Elision 'maerent(em) et'."""),
(862, 'viximus.',
 """“Rhaebus, long — if anything is long for mortals at all —\nhave we lived.""",
 """“Rhaebus, we have lived a long time, if anything at all can be called long for mortal creatures.""",
 """'Rhaebe', vocative of the horse's name. 'diu… diu', the word repeated: the clause 'res siqua diu mortalibus ulla est', 'if any thing at all is lasting for mortals', cuts in before the verb. 'viximus', 'we have lived', held over to the next line, and plural: horse and rider as companions. The perfect can also carry the sense 'our life is done'. Prodelision 'ulla (e)st'."""),
(865, 'pariter;',
 """Either today, victor, those spoils of the bloody man\nand the head of Aeneas you will bring back, and of Lausus's sufferings\nthe avenger you will be with me, or, if opens no way any force,\nyou will fall alongside;""",
 """Either today you will carry back in triumph the spoils and the head of bloodstained Aeneas, and avenge Lausus's sufferings with me, or, if no force can open a way, you will fall at my side;""",
 """'Aut… aut', the two outcomes. 'victor', in apposition to the subject, 'as victor'. 'spolia illa', 'those (famous) spoils', Aeneas's armour. 'cruenti… Aeneae', 'of bloody Aeneas', stained with Lausus's blood. 'caput… referes', carrying back an enemy's head, a savage trophy. 'Lausique dolorum / ultor', 'avenger of Lausus's pains'. 'aperit si nulla viam vis', 'if no force opens the way', with 'si' set late in its clause. 'occumbes', 'you will fall (in death)'; 'pariter', 'equally, together'. Elisions 'spoli(a) illa', 'mec(um) aut'."""),
(866, 'Teucros.”',
 """for not, bravest one, I believe,\ncommands of another to suffer and masters will you deign, the Teucrians.”""",
 """for I do not believe, brave heart, that you will consent to bear a stranger's orders and take Trojans for your masters.”""",
 """'neque enim', 'for not'. 'fortissime', vocative, 'bravest one', said to a horse. 'credo', parenthetic, 'I believe'. 'dignabere', second-person future in '-re', 'you will deign', with two objects: the infinitive 'pati', 'to suffer', and the accusative 'dominos… Teucros', 'Teucrians as masters'. 'iussa aliena', 'another's commands'. The horse is given its master's pride. Elisions 'nequ(e) enim', 'iuss(a) aliena', 'pat(i) et'."""),
(869, 'equina.',
 """He spoke, and, taken up on its back, his accustomed he settled\nlimbs, and his hands, both, with javelins he loaded, sharp,\nwith bronze, as to his head, gleaming, and with a crest shaggy, of horsehair.""",
 """He spoke, and the horse took him on its back; he settled his limbs in the familiar seat and loaded both hands with sharp javelins, his head shining with bronze, bristling with a crest of horsehair.""",
 """'exceptus tergo', 'taken up on its back', 'tergo' ablative of place. 'consueta… membra', 'his accustomed limbs', in the seat they knew. 'iaculis… acutis', 'sharp javelins', framing the second half of the line. 'aere caput fulgens', 'gleaming as to his head with bronze': 'caput' is an accusative of respect, a Greek construction (you saw 'fusus… barbam' at 838); he has taken his helmet down from the tree. 'cristaque hirsutus equina', 'shaggy with a horsehair crest'. Elisions 'manusqu(e) ambas', 'cristaqu(e) hirsutus'."""),
(870, 'dedit:',
 """So his course into the midst swiftly he gave:""",
 """So armed, he charged at speed into the thick of the enemy:""",
 """'Sic', 'so (armed)', 'thus'. 'cursum… dedit', 'gave his course', galloped. 'in medios', 'into the midst', with 'hostes' understood. 'rapidus', an adjective doing the work of an adverb, 'swiftly'. The colon opens onto his state of mind in the lines that follow. Elision 'curs(um) in'."""),
(872, 'virtus.]',
 """there surges, vast,\nin one heart shame, and madness with grief mixed,\n[and love by furies driven, and valour conscious of itself.]""",
 """in that one heart there surged a vast shame, and madness mingled with grief, [and love goaded by the Furies, and valour that knew its own worth.]""",
 """'aestuat', 'surges, boils', like the sea; 'ingens… pudor', 'vast shame', at having let his son die for him. 'uno in corde', 'in one heart', all these at once. 'mixtoque insania luctu', 'and madness, with grief mixed in', ablative absolute. Line 872 is bracketed by Greenough as spurious, and the Latin Library omits it: the same three lines, with 872, describe Turnus at XII.666–668, and the line was probably copied here from there. 'conscia virtus', 'valour conscious (of itself)'. Elisions 'un(o) in', 'mixtoqu(e) insania'."""),
(873, 'vocavit.',
 """And here Aeneas with a great voice three times he called.""",
 """And there he called on Aeneas three times in a loud voice.""",
 """'Aenean', the Greek accusative of 'Aeneas'. 'ter', 'three times', a number of ritual and of challenge. 'magna… voce vocavit', 'called with a great voice', a noun and verb from the same root side by side, an old Latin flourish (figura etymologica). This is a challenge to single combat. Elision 'Atqu(e) hic'."""),
(874, 'precatur:',
 """Aeneas knew him indeed, and gladly prays:""",
 """Aeneas knew that voice, and prayed with joy:""",
 """'agnovit', 'recognised', the voice and the challenge. 'enim', here in its old sense, 'indeed, truly', not 'for'; Virgil keeps this early Latin use now and then. 'laetus', 'glad', at last the chance to meet him. 'precatur', 'prays', the prayer that follows. No elisions."""),
(876, 'manum.”',
 """“So may that father of the gods bring it about, so high Apollo:\nmay you begin to join hand.”""",
 """“So may the great father of the gods grant it, so may Apollo on high: come, begin, and meet me hand to hand.”""",
 """'Sic… faciat', 'so may he make it', the wish-subjunctive, a formula of prayer. 'pater ille deum', 'that (great) father of the gods', Jupiter, 'deum' the old genitive plural (you have seen this often). 'altus Apollo', 'lofty Apollo', a patron of Troy. 'incipias', a jussive subjunctive, 'may you begin'. 'conferre manum', 'to join hand (with mine)', to fight at close quarters. Line 876 is one of the half-lines Virgil left unfinished. No elisions."""),
(877, 'hasta.',
 """So much having spoken, he goes up to meet him with hostile spear.""",
 """No more than that he said, and went to meet him with levelled spear.""",
 """'Tantum effatus', 'having spoken only so much', from 'effor', a solemn verb of speaking. 'infesta… hasta', 'with hostile spear', levelled for attack, ablative of manner, framing the second half of the line. 'subit obvius', 'comes up to meet (him)', 'obvius' an adjective with the force of an adverb. Elision 'Tant(um) effatus'."""),
(879, 'terres?',
 """He, however: “Why me, with snatched away, most savage one, my son,\ndo you terrify?""",
 """But Mezentius answered: “Why do you try to frighten me, cruellest of men, now that you have robbed me of my son?""",
 """'Ille autem', with the verb of speaking left out (you have seen this often). 'erepto… nato', ablative absolute, 'my son having been snatched away', with 'me' the object of 'terres'. 'saevissime', vocative, 'most cruel': the cruel tyrant now calls Aeneas cruel. 'terres', 'do you frighten', held over to the next line. Elisions 'Ill(e) autem', 'm(e) erepto'."""),
(879, 'posses.',
 """This the only way was, by which to destroy me you could.""",
 """This was the only way by which you could destroy me.""",
 """'Haec via sola fuit', 'this was the only road': the killing of his son. 'qua perdere posses', 'by which you could destroy (me)', a relative clause with the subjunctive, 'perdere' with its object understood. Mezentius means that death holds no fear for him now; the real blow has already fallen. No elisions."""),
(880, 'ulli.',
 """Neither death do we shudder at, nor of the gods do we spare any.""",
 """I have no dread of death, and I spare none of the gods.""",
 """'horremus', 'we shudder at', the plural 'we' for 'I'. 'divom… ulli', 'any of the gods', 'divom' the old genitive plural, with 'parcimus' taking the dative. Mezentius was called 'scorner of the gods' at his first appearance (VII.648); he will spare no god his contempt now, not even in death. Elision 'mort(em) horremus'."""),
(882, 'prius.',
 """Cease: for I come to die, and these to you I bring,\ngifts, first.”""",
 """Enough: I have come here to die, and first I bring you these gifts.”""",
 """'Desine', 'stop', leave off your threats. 'moriturus', future participle, 'about to die', 'meaning to die'. 'haec… dona', 'these gifts', said in grim irony of his javelins. 'prius', 'first', before I die. On the closing speech mark, see the next unit. No elisions."""),
(882, 'hostem;',
 """He spoke, and a weapon he hurled at the enemy;""",
 """He spoke, and sent a spear spinning at his enemy;""",
 """The print has 'prius. ”Dixit', with the closing speech mark joined to the next word, a misprint for 'prius.” Dixit', corrected here: the speech ends with 'prius'. 'Dixit', 'he spoke'. 'intorsit', 'twisted, hurled', of the spin given to a thrown spear. 'in hostem', 'at the enemy'. Elision 'telumqu(e) intorsit'."""),
(884, 'umbo.',
 """then another on top, and another, he plants, and he flies\nin a huge circle, but holds them the golden boss.""",
 """then another and another after it he planted, riding round in a wide circle, but the golden boss held them all.""",
 """'inde', 'then'. 'aliud super atque aliud', 'another on top and another', one after another. 'figitque volatque', 'both plants (them) and flies', the double '-que'. 'ingenti gyro', 'in a huge circle', ablative of manner; 'gyrus', a Greek word for a ring, is used of horses wheeling. 'aureus umbo', 'the golden boss', the centre of the shield Vulcan made for Aeneas (VIII.608–731); 'sustinet', 'holds up, withstands'. Elisions 'ind(e) aliud', 'atqu(e) aliud'."""),
(887, 'silvam.',
 """Three times round him standing, in leftward circles he rode,\nweapons with his hand hurling; three times with him the Trojan hero\na monstrous, on his bronzed covering, carries round, forest.""",
 """Three times he rode round him in leftward circles as Aeneas stood his ground, hurling spears; three times the Trojan hero turned, carrying round on his bronze-sheathed shield a monstrous forest of shafts.""",
 """'Ter… ter', 'three times', the number repeated, as Mezentius had called three times (873). 'adstantem', 'him standing firm', Aeneas. 'laevos… in orbes', 'in leftward circles', so that his right, throwing arm faces Aeneas. 'Troïus', the diaeresis marking three syllables. 'immanem… silvam', 'a monstrous forest', the spears stuck in the shield, framing the line. 'aerato… tegmine', 'with bronzed covering', the shield. 'circumfert', 'carries round', turning on the spot to face the rider. Elisions 'circ(um) adstantem', 'imman(em) aerato'."""),
(891, 'hastam.',
 """Then, when of dragging out so many delays, so many spearheads, it wearies him\nto pull out, and he is pressed, engaged in a fight unequal,\nmany things turning in his mind, now at last he bursts out, and between\nthe warrior horse's hollow temples he hurls his spear.""",
 """Then, when he grew tired of dragging out so many delays and plucking out so many spearheads, and found himself hard pressed in an uneven fight, he turned over many plans in his mind and at last broke out, and threw his spear between the hollow temples of the war-horse.""",
 """'ubi… taedet', 'when it wearies (him)', the impersonal 'taedet' with the infinitives 'traxisse', 'to have dragged out', and 'vellere', 'to pull out'. 'tot… tot', 'so many… so many'. 'congressus', 'having engaged', a deponent participle. 'pugna… iniqua', 'an unequal fight', on foot against a rider circling him. 'multa movens animo', 'turning many things over in his mind'. 'erumpit', 'bursts out', from his defence. 'bellatoris equi', 'the warrior horse', the noun 'bellator' used as an adjective. In the Iliad an arrow of Paris strikes one of Nestor's horses in the head and brings his chariot down (Iliad 8.81–86). Elisions 'Ind(e) ubi', 'veller(e) et', 'tand(em) erumpit'."""),
(894, 'armo.',
 """Raises itself upright the four-footed beast, and with its heels the air\nbeats, and the thrown rider, coming down on him itself,\nentangles, and with shoulder thrown out lies on him, head-first.""",
 """The horse reared upright and beat the air with its hooves, then, falling after its thrown rider, pinned him down, and sprawled headlong on top of him with its shoulder out of joint.""",
 """'Tollit se arrectum', 'raises itself upright', rears. 'quadrupes', 'the four-footed one', a stately word for the horse. 'calcibus auras / verberat', 'beats the air with its heels', the verb held over to the next line. 'effusum… equitem', 'the rider poured out', thrown. 'super ipse secutus', 'itself following on top'. 'implicat', 'entangles'. 'eiecto… armo', ablative absolute, 'its shoulder thrown out (of joint)'. 'cernuus', 'face down, head first'. Elisions 's(e) arrectum', 'effusumqu(e) equitem', 'eiectoqu(e) incumbit'."""),
(895, 'Latinique.',
 """With shouting they set on fire the sky, both Trojans and Latins.""",
 """Trojans and Latins alike set the heavens ablaze with their shouting.""",
 """'Clamore incendunt caelum', 'they set the sky on fire with shouting', a bold metaphor: the noise flares up like a blaze. 'Troesque Latinique', 'both Trojans and Latins', the double '-que', Homer's 'both… and'; 'Troes' is the Greek nominative plural. Both armies see that the fight is decided. Elision 'Clamor(e) incendunt'."""),
(898, 'animi?',
 """Flies up Aeneas, and from the scabbard snatches his sword,\nand over him this: “Where now is Mezentius the fierce, and that\nsavage force of spirit?”""",
 """Aeneas sped to him, snatched his sword from its sheath, and standing over him said: “Where now is fierce Mezentius, and that savage force of spirit?”""",
 """'Advolat', 'flies to', at speed. 'vagina… eripit', 'snatches from the sheath', ablative of separation. 'super haec', 'over (him) these (words)', 'super' an adverb, with the verb of speaking left out; some take it as 'besides'. 'Ubi nunc', 'where now', a victor's taunt over a fallen enemy. 'acer', 'keen, fierce'. 'effera vis animi', 'the wild force of spirit', 'effera' from 'efferus', 'savage'. On the closing speech mark, see the next unit. Elision 'vaginaqu(e) eripit'."""),
(899, 'recepit:',
 """In reply the Tyrrhenian, when, at the air\nlooking up, he drank in the sky and his mind recovered:""",
 """The Etruscan answered, as soon as he had looked up and drunk in the air of heaven and come back to his senses:""",
 """The print has 'animi? ”Contra', with the closing speech mark joined to the next word, a misprint for 'animi?” Contra', corrected here: the speech ends with 'animi'. 'Contra', 'in reply', with the verb of speaking left out. 'Tyrrhenus', 'the Etruscan', Mezentius. 'ut', 'when', with the indicative. 'auras suspiciens', 'looking up at the air'. 'hausit caelum', 'drank in the sky', breathed again after his fall had stunned him. 'mentem recepit', 'recovered his mind'. No elisions."""),
(900, 'minaris?',
 """“Bitter enemy, why do you taunt me and death threaten?""",
 """“Bitter enemy, why do you taunt me and threaten me with death?""",
 """Mezentius's last speech. 'Hostis amare', vocative, 'bitter enemy'. 'increpitas', 'do you jeer', the frequentative of 'increpo', the verb used of Aeneas scolding Lausus at 810. 'mortemque minaris', 'and threaten death', 'minor' with the accusative of the thing threatened. The threat is pointless: he does not fear what is coming. No elisions."""),
(902, 'Lausus.',
 """No sin in killing, nor on these terms to battle did I come,\nnor with you did my Lausus strike these pacts for me.""",
 """There is no wrong in killing; I did not come to battle on such terms, nor did my Lausus make any such bargain with you for me.""",
 """'Nullum in caede nefas', 'no sin in slaughter', with 'est' understood: in war, killing is no crime. 'nec sic ad proelia veni', 'nor did I come to battle on these terms', expecting mercy. 'haec… foedera', 'these treaties', a bargain to spare me. 'pepigit', perfect of 'pango', 'fixed, agreed'. 'meus… Lausus', 'my Lausus', the possessive early and the name last. 'mihi', dative of advantage, 'for me'. Elision 'Null(um) in'."""),
(904, 'tegi.',
 """This one thing, by whatever there is for conquered enemies of grace, I beg:\nmy body with earth allow to be covered.""",
 """This one thing I beg of you, by whatever mercy is left for beaten enemies: let my body be covered with earth.""",
 """'Unum hoc', 'this one thing', object of 'oro', 'I beg'. 'per siqua est… venia', 'by (the pardon), if there is any pardon, for conquered enemies', a compressed form of oath. 'patiare', present subjunctive, second person in '-re', 'may you allow', a polite command. 'humo tegi', 'to be covered with earth': burial, which the ancients held necessary for the soul's rest. Hector, dying, begs Achilles to give his body back for burial (Iliad 22.338–343), and is refused. Elisions 'Un(um) hoc', 'siqu(a) est', 'veni(a) hostibus'."""),
(906, 'sepulchro.”',
 """I know that the bitter of my own people\nsurround me hatreds: this, I beg, ward off, this fury,\nand me as a sharer with my son grant to the tomb.”""",
 """I know that my own people's bitter hatred is all around me: shield me, I beg you, from their fury, and let me share my son's tomb.”""",
 """'Scio', 'I know', followed by the accusative and infinitive. 'acerba meorum… odia', 'the bitter hatreds of my own people', the Etruscans who drove him out. 'circumstare', 'stand round'. 'hunc… defende furorem', 'ward off this fury', 'defendo' in its old sense, 'keep off'. 'consortem nati… concede sepulchro', 'grant me to the tomb as my son's partner'; 'sepulchro' is Greenough's spelling of 'sepulcro'. Aeneas does not answer, and Virgil does not say whether the wish was granted. Elisions 'Sci(o) acerba', 'circumstar(e) odia', 'odi(a) hunc'."""),
(908, 'cruore.',
 """So he speaks, and in his throat, not unknowing, receives the sword,\nand with streaming his life pours out over the fields, blood.""",
 """So he spoke, and took the sword in his throat, knowing well what he did, and poured out his life over the fields in a stream of blood.""",
 """The end of Book X. 'Haec loquitur', 'he says this'. 'iugulo', 'in his throat', ablative of place. 'haud inscius', 'not unaware', litotes: he offers his throat to the sword knowingly. 'undanti… cruore', 'with streaming gore', framing the line. 'animam diffundit', 'pours out his life', the soul imagined as carried in the blood. The Latin Library reads 'in arma', 'over his armour', for Greenough's 'in arva', 'over the fields'. Elisions 'iuguloqu(e) haud', 'undantiqu(e) animam'."""),
]

PAIRS = {811: 812, 829: 830, 856: 856, 881: 882, 896: 898}
P = A.part('aeneid-081'); L = A.lines_of(P); paras = {l['n'] for l in L if l['p']}
cuts = A.cut(P, [(u[0], u[1]) for u in U])
sents = []; prev_end_line = None
for (t, ln), (_, _t, l, i, n) in zip(cuts, U):
    u = {'t': t, 'l': l, 'i': i, 'n': n}
    if prev_end_line != ln and ln in paras: u['p'] = True
    u['v'] = True; u['ln'] = ln; sents.append(u)
    prev_end_line = ln + t.count('\n')
    if t.count('\n') != l.count('\n'): print('LINE COUNT', ln, repr(t[:30]), t.count('\n'), l.count('\n'))
    if t.count('\n') > 4: print('TOO LONG', ln)
    if '\n' in i: print('NEWLINE IN i', ln)
    if t.rstrip('”]')[-1] not in A.TERMINAL + ',': print('ENDING', ln, repr(t[-12:]))
    nw = len(n.split())
    if nw > 139 or nw < 15: print('NOTE LENGTH', ln, nw)
    for mk in '“”[]':
        if t.count(mk) != l.count(mk) and ln not in PAIRS and ln not in PAIRS.values(): print('MARK l', ln, mk)
        if mk in '“”' and t.count(mk) != i.count(mk) and ln not in PAIRS and ln not in PAIRS.values(): print('MARK i', ln, mk)
A.jdump({'title': TITLE, 'titleEn': TITLE_EN, 'part': PART, 'about': ABOUT, 'sentences': sents}, os.path.join(HERE, 'units.json'))
print(len(sents), 'units')
